  ('f8c21450-2bdd-5968-b5e0-720a6fa842e3', 'Vicariato São José. Horários da página da paróquia no site da diocese (atualizada em 04/04/2024). Sem telefone nem e-mail na página.', '{"https://diocesedecampomaior.org.br/paroquia/paroquia-de-sao-joao-batista-sao-joao-da-serra/","https://diocesedecampomaior.org.br/paroquia/paroquia-de-sao-joao-batista-sao-joao-da-serra/"}', 'media'),
