  ('44e60b25-4862-5d8e-a99f-e9a135a86d32', 'Vicariato Nossa Senhora da Conceição. Horários da página da paróquia no site da diocese (atualizada em 10/12/2024). Mesmo telefone publicado para a Paróquia São João Batista de Barras. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedecampomaior.org.br/paroquia/paroquia-de-santa-luzia-e-sao-jose-operario-barras/","https://diocesedecampomaior.org.br/paroquia/paroquia-de-santa-luzia-e-sao-jose-operario-barras/"}', 'media'),
  ('c07f3f82-d071-5e47-a2b2-1982e445a3cb', 'Vicariato Nossa Senhora da Conceição. Horários da página da paróquia no site da diocese (atualizada em 10/12/2024). Mesmo telefone publicado para a Paróquia de Santa Luzia e São José Operário de Barras.', '{"https://diocesedecampomaior.org.br/paroquia/paroquia-sao-joao-batista-barras/","https://diocesedecampomaior.org.br/paroquia/paroquia-sao-joao-batista-barras/"}', 'media'),
  ('033ec034-24ab-5640-b9af-d3bf7ec46ad4', 'Vicariato Nossa Senhora da Conceição. Horários da página da paróquia no site da diocese (atualizada em 10/12/2024).', '{"https://diocesedecampomaior.org.br/paroquia/paroquia-de-sao-jose-cabeceiras-do-piaui/","https://diocesedecampomaior.org.br/paroquia/paroquia-de-sao-jose-cabeceiras-do-piaui/"}', 'media'),
